// --- ENTERPRISE INTERFACES & SCHEMA DEFINITIONS ---

export type AccountStatus = 'active' | 'frozen' | 'pending' | 'restricted' | 'audit';
export type AccountType = 'checking' | 'savings' | 'treasury' | 'investment' | 'credit' | 'liquidity_pool';
export type TransactionType = 'credit' | 'debit' | 'wire' | 'internal_transfer' | 'fx_exchange';
export type TransactionStatus = 'completed' | 'pending' | 'flagged' | 'declined' | 'settling';

export interface CustomerAccount {
  id: string;
  accountNumberDisplay: string;
  name: string;
  balance: number;
  availableBalance: number;
  currency: string;
  status: AccountStatus;
  type: AccountType;
  customerId: string;
  institutionId: string;
  institutionLoginId: number;
  createdDate: number;
  balanceDate: number;
  routingNumber: string;
  swiftCode?: string;
  creditLimit?: number;
  interestRate?: number;
}

export interface Transaction {
  id: string;
  accountId: string;
  amount: number;
  date: string;
  timestamp: number;
  description: string;
  merchant?: string;
  category: string;
  type: TransactionType;
  status: TransactionStatus;
  reference: string;
  counterparty?: {
    name: string;
    accountNumber: string;
    bankName: string;
  };
  metadata?: {
    exchangeRate?: number;
    fee?: number;
    riskScore?: number;
    complianceFlag?: boolean;
  };
}

export interface AccountAuditLog {
  id: string;
  accountId: string;
  action: string;
  performedBy: string;
  timestamp: number;
  ipAddress: string;
  status: 'SUCCESS' | 'WARNING' | 'CRITICAL';
}

export interface CashFlowMetric {
  period: string;
  inflow: number;
  outflow: number;
  net: number;
}

// --- QUANTUM STATE STORE & PERSISTENCE HOOKS ---

export interface AccountsViewState {
  accounts: CustomerAccount[];
  selectedAccount: CustomerAccount | null;
  transactions: Transaction[];
  auditLogs: AccountAuditLog[];
  isLoadingAccounts: boolean;
  isLoadingTransactions: boolean;
  accountsError: string | null;
  searchQuery: string;
  selectedCategoryFilter: string;
  selectedTypeFilter: string;
  dateRange: '7d' | '30d' | '90d' | 'ytd' | 'all';
  isSyncing: boolean;
  activeTab: 'overview' | 'ledger' | 'analytics' | 'compliance' | 'settings';
  modalState: {
    type: 'transfer' | 'statement' | 'freeze' | 'new_account' | null;
    isOpen: boolean;
  };
}

